<script lang="ts">
 import * as api from '../../bindings';import {onMount} from 'svelte';import Observation from '../../Observation.svelte';import ErrorNotice from '../../ErrorNotice.svelte';
 let {onchoose,oninspect}:{onchoose:(citation:api.GroundingInput)=>void;oninspect:(kind:string,id:string)=>void}=$props();
 let query=$state(''),submitted='',offset=$state(0),result=$state<api.SearchView|null>(null),preview=$state<api.ObservationView|null>(null),role=$state('supports'),busy=$state(false),error=$state<api.CommandError|null>(null);let live=true,version=0;
 onMount(()=>()=>{live=false;version++;});
 async function search(reset=true){if(reset){offset=0;submitted=query;}const current=++version;busy=true;error=null;try{const page=await api.searchCase({query:submitted,kinds:['observation'],offset,limit:50});if(live&&current===version)result=page;}catch(raw){if(live&&current===version)error=api.asCommandError(raw);}finally{if(live&&current===version)busy=false;}}
 async function inspect(id:string){const current=++version;preview=null;error=null;try{const row=await api.observation(id);if(live&&current===version)preview=row;}catch(raw){if(live&&current===version)error=api.asCommandError(raw);}}
</script>
<details><summary>Choose evidence from this case</summary><label>Find observations<input type="search" bind:value={query} onkeydown={e=>{if(e.key==='Enter'){e.preventDefault();void search();}}}/></label><button type="button" disabled={busy} onclick={()=>void search()}>Find observations</button>
 {#if error}<ErrorNotice {error}/>{/if}{#if result}<p>{result.total} matches. {result.coverage.complete} of {result.coverage.artifacts} documents fully read. No match does not establish absence from unread evidence.</p>{#each result.hits as hit}<button type="button" onclick={()=>void inspect(hit.subject_id)}>{hit.title}: {hit.snippet}</button>{/each}<button type="button" disabled={busy||offset===0} onclick={()=>{offset=Math.max(0,offset-50);void search(false);}}>Previous observations</button><button type="button" disabled={busy||offset+50>=result.total} onclick={()=>{offset+=50;void search(false);}}>Next observations</button>{/if}
 {#if preview}<Observation observation={preview}/><button type="button" onclick={()=>oninspect('document',preview!.lineage.artifact.artifact_id)}>Inspect original source</button><label>Evidence role<select bind:value={role}><option value="supports">Supports</option><option value="contradicts">Contradicts</option><option value="context">Context</option></select></label><button type="button" onclick={()=>onchoose({kind:'observation',id:preview!.observation_id,role})}>Add reviewed citation</button>{/if}</details>
<style>details{margin:16px 0;padding:16px;border:1px solid var(--border);border-radius:var(--radius-control)}label{display:grid;gap:8px}button{margin:8px 8px 8px 0}p{max-width:75ch}</style>
